+func (w *Worker) listen(ctx context.Context, out chan<- uuid.UUID) {
+	Listen(ctx, w.DB, []string{events.Channel, OutboxChannel}, func(_, payload string) {
+		if org, err := uuid.Parse(payload); err == nil {
